import React, { useState, useEffect } from 'react';
import '../styles/components.css';

function AdvancedAnalysisViewer({ plotData, fileName }) {
  const [activeTab, setActiveTab] = useState('connectivity');
  const [expandedImage, setExpandedImage] = useState(null);

  // MEJORA: Más debugging y verificación robusta
  console.log('AdvancedAnalysisViewer - plotData:', plotData);
  console.log('AdvancedAnalysisViewer - plotData.plots:', plotData?.plots);

  const handleImageClick = (base64Image, title) => {
    setExpandedImage({ image: base64Image, title });
  };

  const formatPlotName = (name) => {
    const nameMap = {
      'connectivity': 'Channel Connectivity Matrix',
      'spectral_analysis': 'Spectral Analysis',
      'signal_quality': 'Signal Quality Assessment'
    };
    return nameMap[name] || name.replace(/_/g, ' ').replace(/\b\w/g, l => l.toUpperCase());
  };

  // Definir pestañas
  const tabs = [
    { id: 'connectivity', label: 'Connectivity', icon: '🔗', plotKey: 'connectivity' },
    { id: 'spectral', label: 'Spectral Analysis', icon: '📊', plotKey: 'spectral_analysis' },
    { id: 'quality', label: 'Signal Quality', icon: '📈', plotKey: 'signal_quality' }
  ];

  // Filtrar pestañas - solo si plotData.plots existe
  const availableTabs = plotData?.plots 
    ? tabs.filter(tab => {
        const hasData = plotData.plots[tab.plotKey];
        console.log(`Tab ${tab.id} (${tab.plotKey}): ${hasData ? 'HAS DATA' : 'NO DATA'}`);
        return hasData;
      })
    : [];

  // MOVER useEffect AQUÍ - siempre se ejecuta, sin condiciones
  useEffect(() => {
    if (availableTabs.length > 0 && !availableTabs.find(tab => tab.id === activeTab)) {
      console.log(`Setting active tab to: ${availableTabs[0].id}`);
      setActiveTab(availableTabs[0].id);
    }
  }, [availableTabs.length, activeTab]); // Dependencias simplificadas

  // Verificaciones de datos DESPUÉS de los hooks
  if (!plotData?.plots) {
    console.log('No plotData.plots available');
    return (
      <div className="advanced-analysis-container">
        <div className="no-data-message">
          <p>No advanced analysis data available for {fileName}</p>
          <p>Debug: plotData structure doesn't contain plots</p>
        </div>
      </div>
    );
  }

  if (availableTabs.length === 0) {
    console.log('No available tabs with data');
    return (
      <div className="advanced-analysis-container">
        <div className="no-data-message">
          <p>No advanced analysis plots available for {fileName}</p>
          <p>Available plot keys: {Object.keys(plotData.plots).join(', ')}</p>
          <p>Expected keys: connectivity, spectral_analysis, signal_quality</p>
        </div>
      </div>
    );
  }

  return (
    <div className="advanced-analysis-container">
      <h3>Advanced NIRS Analysis - {fileName}</h3>
      
      <div className="analysis-tabs">
        {availableTabs.map(tab => (
          <button
            key={tab.id}
            className={`tab-button ${activeTab === tab.id ? 'active' : ''}`}
            onClick={() => setActiveTab(tab.id)}
          >
            <span className="tab-icon">{tab.icon}</span>
            {tab.label}
          </button>
        ))}
      </div>

      <div className="analysis-content">
        {activeTab === 'connectivity' && plotData.plots.connectivity && (
          <div className="analysis-section">
            <div className="section-header">
              <h4>Channel Connectivity Analysis</h4>
              <p className="section-description">
                This matrix shows the correlation between different NIRS channels. 
                High correlations may indicate shared physiological responses or artifacts.
              </p>
            </div>
            <div className="plot-container">
              <img
                src={`data:image/png;base64,${plotData.plots.connectivity}`}
                alt="Connectivity Matrix"
                className="analysis-plot"
                onClick={() => handleImageClick(plotData.plots.connectivity, 'Channel Connectivity Matrix')}
              />
            </div>
            <div className="analysis-insights">
              <h5>Interpretation Guidelines:</h5>
              <ul>
                <li><strong>Strong correlations (r &gt; 0.8):</strong> May indicate shared neural activity or systemic artifacts</li>
                <li><strong>Moderate correlations (0.5 &lt; r &lt; 0.8):</strong> Typical for nearby channels</li>
                <li><strong>Weak correlations (r &lt; 0.5):</strong> Independent signals, good for analysis</li>
              </ul>
            </div>
          </div>
        )}

        {activeTab === 'spectral' && plotData.plots.spectral_analysis && (
          <div className="analysis-section">
            <div className="section-header">
              <h4>Spectral Analysis</h4>
              <p className="section-description">
                Power spectral density analysis reveals the frequency components of NIRS signals.
                Different frequency bands correspond to different physiological processes.
              </p>
            </div>
            <div className="plot-container">
              <img
                src={`data:image/png;base64,${plotData.plots.spectral_analysis}`}
                alt="Spectral Analysis"
                className="analysis-plot"
                onClick={() => handleImageClick(plotData.plots.spectral_analysis, 'Spectral Analysis')}
              />
            </div>
            <div className="analysis-insights">
              <h5>Frequency Band Interpretation:</h5>
              <ul>
                <li><strong>0.01-0.08 Hz (Red):</strong> Systemic low-frequency oscillations</li>
                <li><strong>0.08-0.15 Hz (Green):</strong> Respiratory-related oscillations (~0.25 Hz)</li>
                <li><strong>0.15-0.4 Hz (Blue):</strong> Cardiac-related oscillations (~1 Hz)</li>
                <li><strong>Above 0.4 Hz:</strong> High-frequency noise and artifacts</li>
              </ul>
            </div>
          </div>
        )}

        {activeTab === 'quality' && plotData.plots.signal_quality && (
          <div className="analysis-section">
            <div className="section-header">
              <h4>Signal Quality Assessment</h4>
              <p className="section-description">
                Comprehensive analysis of signal quality across all channels to identify 
                potential artifacts and assess data reliability.
              </p>
            </div>
            <div className="plot-container">
              <img
                src={`data:image/png;base64,${plotData.plots.signal_quality}`}
                alt="Signal Quality"
                className="analysis-plot"
                onClick={() => handleImageClick(plotData.plots.signal_quality, 'Signal Quality Assessment')}
              />
            </div>
            <div className="analysis-insights">
              <h5>Quality Metrics:</h5>
              <ul>
                <li><strong>SNR &gt; 10 dB:</strong> Good signal quality</li>
                <li><strong>High correlation with mean:</strong> Potential systemic artifact</li>
                <li><strong>Extreme variance:</strong> May indicate motion artifacts</li>
                <li><strong>Consistent amplitude:</strong> Indicates stable optode contact</li>
              </ul>
            </div>
          </div>
        )}
      </div>

      {/* Modal para imagen expandida */}
      {expandedImage && (
        <div className="expanded-image-overlay" onClick={() => setExpandedImage(null)}>
          <div className="expanded-image-container">
            <div className="expanded-image-header">
              <h3>{expandedImage.title}</h3>
              <button className="close-button" onClick={() => setExpandedImage(null)}>×</button>
            </div>
            <img 
              src={`data:image/png;base64,${expandedImage.image}`}
              alt={expandedImage.title}
              className="expanded-image"
            />
          </div>
        </div>
      )}
    </div>
  );
}

export default AdvancedAnalysisViewer;
